package clock

import (
	"bufio"
	"bytes"
	"cmp"
	"compress/gzip"
	_ "embed"
	"encoding/json/v2"
	"fmt"
	"io"
	"slices"
	"strconv"
	"strings"
	"time"
	"unicode"
	"unicode/utf8"

	"github.com/mozillazg/go-pinyin"
	"golang.org/x/text/runes"
	"golang.org/x/text/transform"
	"golang.org/x/text/unicode/norm"
)

// cities.json is the curated overlay: major cities with Chinese names,
// aliases and the default list (docs/world-clock.md §9.3).
//
//go:embed cities.json
var citiesJSON []byte

// geonames.tsv.gz holds the GeoNames cities with a population of 15,000 or
// more (CC BY 4.0), generated by scripts/data/gencities (docs/world-clock.md §9.2).
//
//go:embed geonames.tsv.gz
var geonamesData []byte

// city is a place with a clock. The index does not keep cities as structs
// (docs/world-clock.md §10): index.at makes one from a row of its table when
// needed. Curated cities are also read from cities.json into it.
type city struct {
	ID        string   `json:"id"`
	GeonameID int      `json:"geonameid"`
	Name      string   `json:"name"`
	Zh        string   `json:"zh"`
	Country   string   `json:"country"`
	CountryZh string   `json:"countryZh"`
	TZ        string   `json:"tz"`
	Aliases   []string `json:"aliases"`

	ascii     string // ASCII name, when it differs from Name
	cc        string // ISO country code ("" for UTC)
	region    string // first-level division (state, province)
	regionZh  string
	curated   bool // from cities.json
	ambiguous bool // another city has the same name

	loc *time.Location
	ord int // position in the index: curated first, then by population
}

// matchKey is a normalized string a query is matched against, with the
// forms scoreKey compares precomputed. The keys of cities are stored as
// keyRecs and made into matchKeys while scoring; countries, zones and the
// local clock keep matchKeys.
type matchKey struct {
	s        string
	w        float64 // weight of a match on this key
	exact    bool    // only an exact match counts (pinyin initials)
	compact  string  // s without spaces
	initials string  // first letters of the words when there are several
}

func newMatchKey(s string, w float64) matchKey {
	k := matchKey{s: s, w: w, compact: strings.ReplaceAll(s, " ", "")}
	if words := strings.FieldsFunc(s, isWordSep); len(words) > 1 {
		var ini strings.Builder
		for _, w := range words {
			r, _ := utf8.DecodeRuneInString(w)
			ini.WriteRune(r)
		}
		k.initials = ini.String()
	}
	return k
}

// isWordSep separates the words of a key: spaces and the slashes of zone
// IDs.
func isWordSep(r rune) bool { return r == ' ' || r == '/' }

// laterWords calls fn with each word of s after the first, as a suffix of s
// starting at the word ("asia/ho chi minh" -> "ho chi minh", "chi minh",
// "minh"). Words are not stored, which saves memory with 30,000 cities.
func laterWords(s string, fn func(rest string) bool) {
	sep := func(b byte) bool { return b == ' ' || b == '/' }
	i := 0
	for i < len(s) && sep(s[i]) { // separators before the first word
		i++
	}
	for i < len(s) && !sep(s[i]) { // the first word
		i++
	}
	for ; i < len(s)-1; i++ {
		if sep(s[i]) && !sep(s[i+1]) && fn(s[i+1:]) {
			return
		}
	}
}

// Weights of the kinds of keys.
const (
	weightName    = 1.0
	weightCountry = 0.8
	weightZone    = 0.85
	// scoreOffset and scoreAbbr are the scores of cities found by UTC offset
	// ("utc+8") or time zone abbreviation ("pst").
	scoreOffset = 0.9
	scoreAbbr   = 0.9
)

// country is a country of the GeoNames data with its cities.
type country struct {
	code, name, zh string
	keys           []matchKey
	cities         []int32 // ords, ascending
}

// zone is an IANA time zone with its cities.
type zone struct {
	id     string
	loc    *time.Location
	keys   []matchKey
	cities []int32 // ords, ascending
	ord    uint16  // position in index.zones
}

// index holds the cities with their match keys and locations, the
// countries and zones, and the lookup tables (docs/world-clock.md §9.5). The
// cities are a compact table (§10): fixed-size rows whose strings are in one
// blob, and match keys in one array; it is read-only once built.
type index struct {
	rows    []cityRow
	keyRecs []keyRec // the match keys of the cities, in ord order
	blob    string   // names, normalized keys, pinyin and initials
	curated []*city  // the curated cities (ords 0 to len-1), from cities.json
	ccs     []ccRec  // country codes of the rows (cityRow.cc - 1)
	regions []regionRec

	countries []*country
	zones     []*zone
	zoneByID  map[string]*zone
	names     nameIndex

	byID        map[string]int32 // ords of the curated cities
	byGeonameID []int32          // ords of the GeoNames cities by GeoNames ID
	zoneByLower map[string]*zone // lowercase zone IDs
}

// cityRow is a city in the table. Strings are offsets into index.blob with
// their lengths (names are at most 255 bytes); the country code, region and
// zone are indexes into small tables.
type cityRow struct {
	name, ascii, zh             uint32
	keys                        uint32 // first match key in index.keyRecs
	gid                         uint32 // GeoNames ID; 0 for curated cities without one
	nameLen, asciiLen, zhLen, n uint8  // n: number of match keys
	cc, region, zone            uint16 // cc and region 1-based (0: none); zone 0-based
	flags                       uint8
}

const (
	rowCurated = 1 << iota
	rowAmbiguous
)

// keyRec is a match key in index.blob: its compact form (s without spaces)
// at off; then s when it has spaces, and the initials when it has several
// words. Exact keys are s at off.
type keyRec struct {
	off    uint32
	clen   uint16 // length of the compact form
	spaces uint8  // spaces in s: s is the compact form when 0
	ilen   uint8  // 0: no initials
	kind   uint8
}

// Kinds of keys: the weight, and whether only an exact match counts.
const (
	kindCountry = 1 << iota // weightCountry; else weightName
	kindExact
)

type ccRec struct {
	code string
	co   *country // nil when the data has no such country
}

type regionRec struct {
	name, zh strRef
}

// strRef is a string in index.blob.
type strRef struct{ off, n uint32 }

func (idx *index) str(r strRef) string { return idx.blob[r.off : r.off+r.n] }

func (idx *index) sub(off uint32, n uint8) string { return idx.blob[off : off+uint32(n)] }

// len is the number of cities.
func (idx *index) len() int { return len(idx.rows) }

// name, ascii and zh are the names of the city at ord.
func (idx *index) name(ord int32) string {
	r := &idx.rows[ord]
	return idx.sub(r.name, r.nameLen)
}

func (idx *index) ascii(ord int32) string {
	r := &idx.rows[ord]
	return idx.sub(r.ascii, r.asciiLen)
}

func (idx *index) zh(ord int32) string {
	r := &idx.rows[ord]
	return idx.sub(r.zh, r.zhLen)
}

// at returns the city at ord. Its strings share the index's memory; only the
// ID of a GeoNames city is made.
func (idx *index) at(ord int32) *city {
	r := &idx.rows[ord]
	z := idx.zones[r.zone]
	c := &city{
		GeonameID: int(r.gid),
		Name:      idx.sub(r.name, r.nameLen),
		Zh:        idx.sub(r.zh, r.zhLen),
		TZ:        z.id,
		ascii:     idx.sub(r.ascii, r.asciiLen),
		curated:   r.flags&rowCurated != 0,
		ambiguous: r.flags&rowAmbiguous != 0,
		loc:       z.loc,
		ord:       int(ord),
	}
	if r.cc > 0 {
		cc := idx.ccs[r.cc-1]
		c.cc = cc.code
		if cc.co != nil {
			c.Country, c.CountryZh = cc.co.name, cc.co.zh
		}
	}
	if r.region > 0 {
		reg := idx.regions[r.region-1]
		c.region, c.regionZh = idx.str(reg.name), idx.str(reg.zh)
	}
	if c.curated {
		cu := idx.curated[ord]
		c.ID, c.Country, c.CountryZh, c.Aliases = cu.ID, cu.Country, cu.CountryZh, cu.Aliases
	} else {
		c.ID = strconv.Itoa(int(r.gid))
	}
	return c
}

// key returns match key k.
func (idx *index) key(k *keyRec) matchKey {
	o := k.off + uint32(k.clen)
	compact := idx.blob[k.off:o]
	m := matchKey{s: compact, w: weightName, exact: k.kind&kindExact != 0}
	if k.kind&kindCountry != 0 {
		m.w = weightCountry
	}
	if m.exact {
		return m
	}
	m.compact = compact
	if k.spaces > 0 {
		n := uint32(k.clen) + uint32(k.spaces)
		m.s = idx.blob[o : o+n]
		o += n
	}
	if k.ilen > 0 {
		m.initials = idx.sub(o, k.ilen)
	}
	return m
}

// s returns the string of key k and its offset in the blob.
func (idx *index) s(k *keyRec) (string, uint32) {
	if k.spaces == 0 {
		return idx.blob[k.off : k.off+uint32(k.clen)], k.off
	}
	o := k.off + uint32(k.clen)
	return idx.blob[o : o+uint32(k.clen)+uint32(k.spaces)], o
}

// cityKeyRecs are the match keys of the city at ord.
func (idx *index) cityKeyRecs(ord int32) []keyRec {
	r := &idx.rows[ord]
	return idx.keyRecs[r.keys : r.keys+uint32(r.n)]
}

// keys returns the match keys of the city at ord.
func (idx *index) keys(ord int32) []matchKey {
	var out []matchKey
	for i := range idx.cityKeyRecs(ord) {
		out = append(out, idx.key(&idx.cityKeyRecs(ord)[i]))
	}
	return out
}

// bestKey is the best weighted score of q against the keys of the city at
// ord.
func (idx *index) bestKey(q, qc string, ord int32) float64 {
	best := 0.0
	keys := idx.cityKeyRecs(ord)
	for i := range keys {
		k := idx.key(&keys[i])
		best = max(best, k.w*scoreKey(q, qc, &k))
	}
	return best
}

// loadIndex loads the embedded cities.
func loadIndex() (*index, error) {
	return buildIndex(citiesJSON, bytes.NewReader(geonamesData))
}

// builder builds an index.
type builder struct {
	idx     *index
	blob    []byte
	names   [3]string // the names of the city being added
	nameOff [3]uint32 // and their offsets
	ccs     map[string]uint16
	regions map[string]uint16
	norm    []string // normalized names, by ord
}

// add adds s to the blob and returns its offset. A key that is one of the
// names of the city being added (Chinese names usually are) shares it.
func (b *builder) add(s string) uint32 {
	if s == "" {
		return 0
	}
	for i, n := range b.names {
		if n == s {
			return b.nameOff[i]
		}
	}
	off := uint32(len(b.blob))
	b.blob = append(b.blob, s...)
	return off
}

func (b *builder) ref(s string) strRef { return strRef{b.add(s), uint32(len(s))} }

// short adds a name of at most 255 bytes.
func (b *builder) short(s string) (uint32, uint8, error) {
	if len(s) > 255 {
		return 0, 0, fmt.Errorf("clock: name too long: %q", s)
	}
	return b.add(s), uint8(len(s)), nil
}

// addKey adds match key k.
func (b *builder) addKey(k matchKey) error {
	r := keyRec{}
	if k.w == weightCountry {
		r.kind |= kindCountry
	} else if k.w != weightName {
		return fmt.Errorf("clock: key %q: weight %v", k.s, k.w)
	}
	if k.exact {
		r.kind |= kindExact
	}
	if len(k.s) > maxNameLen || len(k.s)-len(k.compact) > 255 || len(k.initials) > 255 {
		return fmt.Errorf("clock: key too long: %q", k.s)
	}
	if k.exact {
		r.off, r.clen = b.add(k.s), uint16(len(k.s))
	} else if k.compact == k.s && k.initials == "" {
		r.off, r.clen = b.add(k.s), uint16(len(k.s))
	} else {
		// The forms follow each other: not interned.
		r.off, r.clen = uint32(len(b.blob)), uint16(len(k.compact))
		b.blob = append(b.blob, k.compact...)
		if k.compact != k.s {
			r.spaces = uint8(len(k.s) - len(k.compact))
			b.blob = append(b.blob, k.s...)
		}
		r.ilen = uint8(len(k.initials))
		b.blob = append(b.blob, k.initials...)
	}
	b.idx.keyRecs = append(b.idx.keyRecs, r)
	return nil
}

// addCity appends city c (its keys are computed here) with region reg.
func (b *builder) addCity(c *city, reg regionName, z *zone) error {
	idx := b.idx
	var r cityRow
	var err error
	b.names = [3]string{}
	if r.name, r.nameLen, err = b.short(c.Name); err != nil {
		return err
	}
	if r.ascii, r.asciiLen, err = b.short(c.ascii); err != nil {
		return err
	}
	if r.zh, r.zhLen, err = b.short(c.Zh); err != nil {
		return err
	}
	b.names = [3]string{c.Name, c.ascii, c.Zh}
	b.nameOff = [3]uint32{r.name, r.ascii, r.zh}
	r.gid = uint32(c.GeonameID)
	r.zone = z.ord
	if c.cc != "" {
		i, ok := b.ccs[c.cc]
		if !ok {
			idx.ccs = append(idx.ccs, ccRec{code: c.cc})
			i = uint16(len(idx.ccs))
			b.ccs[c.cc] = i
		}
		r.cc = i
	}
	if reg.name != "" || reg.zh != "" {
		key := reg.name + "\t" + reg.zh
		i, ok := b.regions[key]
		if !ok {
			b.names = [3]string{}
			idx.regions = append(idx.regions, regionRec{b.ref(reg.name), b.ref(reg.zh)})
			i = uint16(len(idx.regions))
			b.regions[key] = i
		}
		r.region = i
	}
	if c.curated {
		r.flags |= rowCurated
	}
	keys := cityKeys(c)
	if len(keys) > 255 {
		return fmt.Errorf("clock: city %s: too many keys", c.Name)
	}
	r.keys, r.n = uint32(len(idx.keyRecs)), uint8(len(keys))
	for _, k := range keys {
		if err := b.addKey(k); err != nil {
			return err
		}
	}
	ord := int32(len(idx.rows))
	idx.rows = append(idx.rows, r)
	b.norm = append(b.norm, normalize(c.Name))
	z.cities = append(z.cities, ord)
	return nil
}

// buildIndex reads the curated cities (JSON) and the gzip'd GeoNames data,
// merges them, loads the time zones and builds the match keys and lookup
// tables.
func buildIndex(curatedJSON []byte, geonames io.Reader) (*index, error) {
	var curated []*city
	if err := json.Unmarshal(curatedJSON, &curated); err != nil {
		return nil, fmt.Errorf("clock: cities.json: %w", err)
	}
	g, err := parseGeonames(geonames)
	if err != nil {
		return nil, err
	}
	idx := &index{zoneByID: map[string]*zone{}, byID: map[string]int32{}, curated: curated}
	byGeoname := map[int]*city{}
	for i, c := range curated {
		if _, dup := idx.byID[c.ID]; dup {
			return nil, fmt.Errorf("clock: duplicate city id %q", c.ID)
		}
		if _, err := idx.zone(c.TZ); err != nil {
			return nil, fmt.Errorf("clock: city %s: %w", c.ID, err)
		}
		c.curated = true
		c.ord = i
		idx.byID[c.ID] = int32(i)
		if c.GeonameID != 0 {
			byGeoname[c.GeonameID] = c
		}
	}
	countries := map[string]*country{}
	for _, c := range g.countries {
		countries[c.code] = c
		idx.countries = append(idx.countries, c)
	}
	// The curated cities get their country code and region from their
	// GeoNames rows, which are left out.
	curatedRegion := make([]regionName, len(curated))
	for _, row := range g.cities {
		if c, ok := byGeoname[row.id]; ok {
			c.cc = row.cc
			curatedRegion[c.ord] = g.regions[row.cc+"."+row.admin1]
		}
	}
	b := &builder{idx: idx, blob: make([]byte, 0, 2<<20),
		ccs: map[string]uint16{}, regions: map[string]uint16{}}
	idx.rows = make([]cityRow, 0, len(curated)+len(g.cities))
	for i, c := range curated {
		z := idx.zoneByID[c.TZ]
		if err := b.addCity(c, curatedRegion[i], z); err != nil {
			return nil, err
		}
	}
	var tmp city
	for _, row := range g.cities {
		if _, ok := byGeoname[row.id]; ok {
			continue
		}
		z, err := idx.zone(row.tz)
		if err != nil {
			continue // a zone this Go does not know; the generator checks them
		}
		tmp = city{GeonameID: row.id, Name: row.name, ascii: row.ascii, Zh: row.zh, TZ: row.tz, cc: row.cc}
		if err := b.addCity(&tmp, g.regions[row.cc+"."+row.admin1], z); err != nil {
			return nil, err
		}
	}
	idx.rows = trim(idx.rows)
	idx.blob = string(b.blob)
	idx.keyRecs = trim(idx.keyRecs)
	idx.finish(countries, b.norm)
	for _, z := range idx.zones {
		z.cities = trim(z.cities)
	}
	for _, co := range idx.countries {
		co.cities = trim(co.cities)
	}
	return idx, nil
}

// trim returns s without spare capacity worth copying for: the index lives
// long.
func trim[S ~[]E, E any](s S) S {
	if cap(s)-len(s) > len(s)/16 {
		return slices.Clone(s)
	}
	return s
}

// zone returns the zone with IANA ID id, loading it the first time.
func (idx *index) zone(id string) (*zone, error) {
	if z, ok := idx.zoneByID[id]; ok {
		return z, nil
	}
	loc, err := time.LoadLocation(id)
	if err != nil {
		return nil, err
	}
	z := &zone{id: id, loc: loc, ord: uint16(len(idx.zones))}
	z.keys = append(z.keys, newMatchKey(normalize(id), weightZone))
	if _, last, ok := strings.Cut(id, "/"); ok {
		if i := strings.LastIndex(last, "/"); i >= 0 {
			last = last[i+1:]
		}
		z.keys = append(z.keys, newMatchKey(normalize(strings.ReplaceAll(last, "_", " ")), weightZone))
	}
	idx.zoneByID[id] = z
	idx.zones = append(idx.zones, z)
	return z, nil
}

// finish computes what needs all cities: the countries' city lists and
// keys, ambiguous names (norm are the normalized names), the lookup tables
// and the name index.
func (idx *index) finish(countries map[string]*country, norm []string) {
	for i := range idx.ccs {
		idx.ccs[i].co = countries[idx.ccs[i].code]
	}
	names := map[string]int{}
	for ord := range idx.rows {
		r := &idx.rows[ord]
		if r.cc > 0 {
			if co := idx.ccs[r.cc-1].co; co != nil {
				co.cities = append(co.cities, int32(ord))
			}
		}
		names[norm[ord]]++
		if r.flags&rowCurated == 0 {
			idx.byGeonameID = append(idx.byGeonameID, int32(ord))
		}
	}
	for ord := range idx.rows {
		if names[norm[ord]] > 1 {
			idx.rows[ord].flags |= rowAmbiguous
		}
	}
	slices.SortFunc(idx.byGeonameID, func(a, b int32) int {
		return cmp.Compare(idx.rows[a].gid, idx.rows[b].gid)
	})
	idx.zoneByLower = make(map[string]*zone, len(idx.zones))
	for _, z := range idx.zones {
		idx.zoneByLower[strings.ToLower(z.id)] = z
	}
	for _, co := range idx.countries {
		co.keys = nil
		add := func(s string) {
			if s = normalize(s); s != "" {
				co.keys = append(co.keys, newMatchKey(s, weightCountry))
			}
		}
		add(co.name)
		add(co.zh)
		if full, initials := pinyinOf(co.zh); full != "" {
			add(full)
			co.keys = append(co.keys, matchKey{s: initials, w: weightCountry, exact: true})
		}
	}
	idx.names = newNameIndex(idx)
}

// chinaCodes are the countries whose cities' pinyin initials are matched
// ("sz" for 深圳); initials of transliterated foreign names mean nothing.
var chinaCodes = map[string]bool{"CN": true, "TW": true, "HK": true, "MO": true}

// cityKeys returns the match keys of c: names, Chinese name and its pinyin,
// aliases, and for curated cities also their country. Countries and zones of
// all cities are matched through index.countries and index.zones.
func cityKeys(c *city) []matchKey {
	var keys []matchKey
	add := func(s string, w float64) {
		if s = normalize(s); s != "" && !slices.ContainsFunc(keys, func(k matchKey) bool { return k.s == s && k.w == w }) {
			keys = append(keys, newMatchKey(s, w))
		}
	}
	addHan := func(s string, w float64, initials bool) {
		add(s, w)
		if full, ini := pinyinOf(s); full != "" {
			add(full, w)
			// Initials only count as exact matches: as prefixes or
			// substrings they would match almost anything.
			if initials {
				keys = append(keys, matchKey{s: ini, w: w, exact: true})
			}
		}
	}
	add(c.Name, weightName)
	add(c.ascii, weightName)
	addHan(c.Zh, weightName, c.curated || chinaCodes[c.cc])
	for _, a := range c.Aliases {
		addHan(a, weightName, true)
	}
	if c.curated {
		add(c.Country, weightCountry)
		addHan(c.CountryZh, weightCountry, true)
	}
	return keys
}

// geonames is the parsed GeoNames data file.
type geonames struct {
	countries []*country
	regions   map[string]regionName // "US.IL"
	cities    []geonameRow          // by population, largest first
}

type regionName struct{ name, zh string }

type geonameRow struct {
	id                              int
	name, ascii, zh, cc, admin1, tz string
}

// parseGeonames parses the gzip'd TSV written by scripts/data/gencities:
// sections "#countries" (code, name, Chinese name), "#admin1" ("US.IL",
// name, Chinese name) and "#cities" (GeoNames ID, name, ASCII name, Chinese
// name, country code, admin1 code, time zone). Other lines starting with
// "#" are comments.
func parseGeonames(r io.Reader) (*geonames, error) {
	zr, err := gzip.NewReader(r)
	if err != nil {
		return nil, fmt.Errorf("clock: city data: %w", err)
	}
	g := &geonames{regions: map[string]regionName{}}
	sc := bufio.NewScanner(zr)
	section := ""
	line := 0
	for sc.Scan() {
		line++
		s := sc.Text()
		if s == "" {
			continue
		}
		if s[0] == '#' {
			switch s {
			case "#countries", "#admin1", "#cities":
				section = s
			}
			continue
		}
		f := strings.Split(s, "\t")
		bad := func() error { return fmt.Errorf("clock: city data line %d: %d fields in %s", line, len(f), section) }
		switch section {
		case "#countries":
			if len(f) != 3 {
				return nil, bad()
			}
			g.countries = append(g.countries, &country{code: f[0], name: f[1], zh: f[2]})
		case "#admin1":
			if len(f) != 3 {
				return nil, bad()
			}
			g.regions[f[0]] = regionName{f[1], f[2]}
		case "#cities":
			if len(f) != 7 {
				return nil, bad()
			}
			id, err := strconv.Atoi(f[0])
			if err != nil {
				return nil, fmt.Errorf("clock: city data line %d: %w", line, err)
			}
			g.cities = append(g.cities, geonameRow{id: id, name: f[1], ascii: f[2], zh: f[3], cc: f[4], admin1: f[5], tz: f[6]})
		default:
			return nil, fmt.Errorf("clock: city data line %d: outside a section", line)
		}
	}
	if err := sc.Err(); err != nil {
		return nil, fmt.Errorf("clock: city data: %w", err)
	}
	return g, nil
}

var pinyinArgs = pinyin.NewArgs()

// pinyinOf returns the pinyin of the Han characters in s ("北京" ->
// "beijing", "bj"), or "" when s has none.
func pinyinOf(s string) (full, initials string) {
	if s == "" {
		return "", ""
	}
	syl := pinyin.LazyPinyin(s, pinyinArgs)
	if len(syl) == 0 {
		return "", ""
	}
	var ini strings.Builder
	for _, p := range syl {
		ini.WriteByte(p[0])
	}
	return strings.Join(syl, ""), ini.String()
}

// stripMarks removes diacritics: "São Paulo" -> "Sao Paulo".
var stripMarks = transform.Chain(norm.NFD, runes.Remove(runes.In(unicode.Mn)), norm.NFC)

// normalize lowercases s, removes diacritics and punctuation that is often
// left out ("Xi'an", "Washington, D.C.") and collapses spaces. Slashes of
// time zone IDs are kept.
func normalize(s string) string {
	ascii := true
	for i := 0; i < len(s); i++ {
		if s[i] >= utf8.RuneSelf {
			ascii = false
			break
		}
	}
	if !ascii {
		if t, _, err := transform.String(stripMarks, s); err == nil {
			s = t
		}
	}
	s = strings.Map(func(r rune) rune {
		switch r {
		case '\'', '’', '.', ',':
			return -1
		case '-', '_':
			return ' '
		}
		return unicode.ToLower(r)
	}, s)
	return strings.Join(strings.Fields(s), " ")
}

// scoreKey scores query q (normalized; qc is q without spaces) against
// key k: 1 for an exact match, less for prefixes, word prefixes, initials,
// substrings and subsequences, 0 for no match. Scores of at least
// strongScore come from the name index; weaker ones (substrings and
// subsequences) only from a full scan.
func scoreKey(q, qc string, k *matchKey) float64 {
	if k.exact {
		if q == k.s {
			return 1
		}
		return 0
	}
	kc := k.compact
	switch {
	case q == k.s, qc == kc: // "newyork"
		return 1
	case strings.HasPrefix(kc, qc):
		return 0.9
	}
	// A query without separators is a prefix of a word exactly when it is a
	// prefix of the rest of the key starting at that word.
	if !strings.ContainsAny(q, " /") {
		word := false
		laterWords(k.s, func(rest string) bool {
			word = strings.HasPrefix(rest, q)
			return word
		})
		if word {
			return 0.8 // "york", "shanghai" in "asia/shanghai"
		}
	}
	if k.initials != "" && len(qc) >= 2 {
		switch {
		case k.initials == qc:
			return 0.9 // "hcmc"
		case strings.HasPrefix(k.initials, qc):
			return 0.75
		}
	}
	if utf8.RuneCountInString(qc) >= 2 && strings.Contains(kc, qc) {
		return 0.6
	}
	if len(qc) >= 4 && qc[0] == kc[0] && subsequence(qc, kc) {
		return 0.3 + 0.2*float64(len(qc))/float64(len(kc))
	}
	return 0
}

// strongScore is the least score scoreKey gives for an exact match, a
// prefix, a word prefix or initials; substrings and subsequences score less.
const strongScore = 0.75

// subsequence reports whether the runes of q appear in k in order.
func subsequence(q, k string) bool {
	qr := []rune(q)
	i := 0
	for _, r := range k {
		if i < len(qr) && r == qr[i] {
			i++
		}
	}
	return i == len(qr)
}

// offsetQuery is a query for a UTC offset.
type offsetQuery struct {
	seconds int
	ok      bool
}

// parseOffset parses "utc+8", "gmt-5:30", "UTC+0545", "+8" and "utc" (a
// normalized query) as a UTC offset.
func parseOffset(q string) offsetQuery {
	q = strings.ReplaceAll(q, " ", "")
	q = strings.ReplaceAll(q, "−", "-") // minus sign
	rest, named := strings.CutPrefix(q, "utc")
	if !named {
		rest, named = strings.CutPrefix(q, "gmt")
	}
	if rest == "" {
		return offsetQuery{0, named}
	}
	sign := 1
	switch rest[0] {
	case '+':
	case '-':
		sign = -1
	default:
		return offsetQuery{}
	}
	rest = rest[1:]
	h, m, colon := strings.Cut(rest, ":")
	if !colon && len(rest) > 2 {
		h, m = rest[:len(rest)-2], rest[len(rest)-2:] // "0530"
	}
	hours, ok := digits(h, 1, 2)
	if !ok || hours > 14 {
		return offsetQuery{}
	}
	minutes := 0
	if colon || m != "" {
		if minutes, ok = digits(m, 2, 2); !ok || minutes >= 60 {
			return offsetQuery{}
		}
	}
	return offsetQuery{sign * (hours*3600 + minutes*60), true}
}

// digits parses a decimal number of minLen to maxLen ASCII digits.
func digits(s string, minLen, maxLen int) (int, bool) {
	if len(s) < minLen || len(s) > maxLen {
		return 0, false
	}
	n := 0
	for _, r := range s {
		if r < '0' || r > '9' {
			return 0, false
		}
		n = n*10 + int(r-'0')
	}
	return n, true
}

// abbreviations maps common time zone abbreviations to the zones of the
// cities they stand for. Abbreviations are ambiguous; this is a fixed,
// documented choice (docs/world-clock.md §4). "cst" lists both US Central
// and China Standard Time.
var abbreviations = func() map[string][]string {
	us := map[string][]string{
		"pt":  {"America/Los_Angeles", "America/Vancouver"},
		"mt":  {"America/Denver", "America/Phoenix", "America/Edmonton"},
		"ct":  {"America/Chicago", "America/Mexico_City"},
		"et":  {"America/New_York", "America/Toronto"},
		"at":  {"America/Halifax", "America/Puerto_Rico"},
		"akt": {"America/Anchorage"},
		"nt":  {"America/St_Johns"},
	}
	m := map[string][]string{
		"gmt":  {"UTC", "Europe/London", "Europe/Dublin", "Africa/Accra", "Africa/Dakar", "Atlantic/Reykjavik"},
		"utc":  {"UTC"},
		"bst":  {"Europe/London"},
		"ist":  {"Asia/Kolkata"},
		"wet":  {"Europe/Lisbon"},
		"west": {"Europe/Lisbon"},
		"cet": {"Europe/Paris", "Europe/Berlin", "Europe/Madrid", "Europe/Rome", "Europe/Amsterdam", "Europe/Brussels",
			"Europe/Luxembourg", "Europe/Zurich", "Europe/Vienna", "Europe/Copenhagen", "Europe/Oslo", "Europe/Stockholm",
			"Europe/Warsaw", "Europe/Prague", "Europe/Budapest", "Europe/Belgrade", "Europe/Zagreb", "Africa/Algiers", "Africa/Tunis"},
		"eet": {"Europe/Athens", "Europe/Helsinki", "Europe/Kyiv", "Europe/Bucharest", "Europe/Sofia", "Europe/Riga",
			"Europe/Vilnius", "Europe/Tallinn", "Africa/Cairo", "Asia/Beirut"},
		"msk":  {"Europe/Moscow"},
		"trt":  {"Europe/Istanbul"},
		"gst":  {"Asia/Dubai", "Asia/Muscat"},
		"pkt":  {"Asia/Karachi"},
		"npt":  {"Asia/Kathmandu"},
		"ict":  {"Asia/Bangkok", "Asia/Ho_Chi_Minh", "Asia/Phnom_Penh"},
		"wib":  {"Asia/Jakarta"},
		"sgt":  {"Asia/Singapore"},
		"myt":  {"Asia/Kuala_Lumpur"},
		"pht":  {"Asia/Manila"},
		"hkt":  {"Asia/Hong_Kong"},
		"jst":  {"Asia/Tokyo"},
		"kst":  {"Asia/Seoul"},
		"aest": {"Australia/Sydney", "Australia/Melbourne", "Australia/Brisbane"},
		"aedt": {"Australia/Sydney", "Australia/Melbourne"},
		"acst": {"Australia/Adelaide", "Australia/Darwin"},
		"acdt": {"Australia/Adelaide"},
		"awst": {"Australia/Perth"},
		"nzst": {"Pacific/Auckland"},
		"nzdt": {"Pacific/Auckland"},
		"hst":  {"Pacific/Honolulu"},
		"sast": {"Africa/Johannesburg"},
		"eat":  {"Africa/Nairobi", "Africa/Addis_Ababa", "Africa/Dar_es_Salaam"},
		"wat":  {"Africa/Lagos", "Africa/Kinshasa", "Africa/Luanda"},
		"brt":  {"America/Sao_Paulo"},
		"art":  {"America/Argentina/Buenos_Aires"},
	}
	// US-style zones: "pt", "pst" and "pdt" all mean Pacific Time.
	for k, zones := range us {
		base := k[:len(k)-1]
		for _, v := range []string{k, base + "st", base + "dt"} {
			m[v] = zones
		}
	}
	m["cst"] = slices.Concat(m["cst"], []string{"Asia/Shanghai", "Asia/Taipei", "Asia/Macau", "Asia/Hong_Kong"})
	m["cest"], m["eest"] = m["cet"], m["eet"]
	return m
}()

// lookup finds the city a preference entry or favorite names: an ID, an
// English or Chinese name, an alias or an IANA time zone. Among cities of
// the same name the first (curated, then larger) wins. An IANA zone that no
// city uses becomes a city of its own named after the zone.
func (idx *index) lookup(s string) (*city, bool) {
	s = strings.TrimSpace(s)
	if s == "" {
		return nil, false
	}
	if c := idx.city(s); c != nil {
		return c, true
	}
	if id, ok := strings.CutPrefix(s, zonePrefix); ok {
		s = id
	}
	n := normalize(s)
	if ord := idx.withKey(n, func(ord int32) bool {
		return normalize(idx.name(ord)) == n || idx.ascii(ord) != "" && normalize(idx.ascii(ord)) == n
	}); ord >= 0 {
		return idx.at(ord), true
	}
	if ord := idx.withKey(n, func(ord int32) bool { return idx.zh(ord) == s }); ord >= 0 {
		return idx.at(ord), true
	}
	if z := idx.zoneByLower[strings.ToLower(s)]; z != nil && len(z.cities) > 0 {
		return idx.at(z.cities[0]), true
	}
	if ord := idx.withKey(n, func(ord int32) bool {
		return int(ord) < len(idx.curated) &&
			slices.ContainsFunc(idx.curated[ord].Aliases, func(a string) bool { return normalize(a) == n })
	}); ord >= 0 {
		return idx.at(ord), true
	}
	if !strings.Contains(s, "/") {
		return nil, false
	}
	loc, err := time.LoadLocation(s)
	if err != nil {
		return nil, false
	}
	name := s[strings.LastIndex(s, "/")+1:]
	return &city{ID: zonePrefix + s, Name: strings.ReplaceAll(name, "_", " "), TZ: s, loc: loc, ord: idx.len()}, true
}

// city returns the city with ID id, or nil.
func (idx *index) city(id string) *city {
	if ord, ok := idx.byID[id]; ok {
		return idx.at(ord)
	}
	g, err := strconv.Atoi(id)
	if err != nil || g < 0 || g > 1<<32-1 {
		return nil
	}
	i, ok := slices.BinarySearchFunc(idx.byGeonameID, uint32(g), func(ord int32, g uint32) int {
		return cmp.Compare(idx.rows[ord].gid, g)
	})
	if !ok || strconv.Itoa(int(idx.rows[idx.byGeonameID[i]].gid)) != id {
		return nil
	}
	return idx.at(idx.byGeonameID[i])
}

// withKey returns the first city with a match key whose compact form is
// that of normalized string n and for which match is true, or -1.
func (idx *index) withKey(n string, match func(ord int32) bool) int32 {
	for _, ord := range idx.names.exactly(strings.ReplaceAll(n, " ", "")) {
		if match(ord) {
			return ord
		}
	}
	return -1
}

// zonePrefix starts the ID of a city made up from an IANA zone.
const zonePrefix = "tz:"
